/* ASH_BELL_CHAMBER_BEGIN */
(() => {
  const level = 9;
  const surface = {
    cast:[59,50,41], belly:[72,58,43], lip:[115,85,50],
    inside:[16,12,10], oak:[61,44,31], oakEdge:[92,66,43],
    iron:[71,68,62], ironEdge:[115,102,76], ash:[149,118,71],
    plaque:[55,44,37], cord:[114,91,63], keeper:[240,133,51]
  };
  const pixels = /* ASH_BELL_SWATCHES_BEGIN */ {
    "cast": "",
    "belly": "",
    "lip": "",
    "inside": "",
    "oak": "",
    "oakEdge": "",
    "iron": "",
    "ironEdge": "",
    "ash": "",
    "plaque": "",
    "cord": "",
    "keeper": ""
  } /* ASH_BELL_SWATCHES_END */;
  const tiles = Object.keys(surface);
  const tile = 64, gap = 2, size = tile - gap * 2, columns = 4;
  const atlasWidth = columns * tile, atlasHeight = tiles.length / columns * tile;
  const activeBells = new WeakMap();

  function surfaceAtlas() {
    const atlas = Z(e0(ctx => {
      const img = ctx.createImageData(atlasWidth,atlasHeight);
      for (const [slot,name] of tiles.entries()) {
        const u = slot % columns * tile, v = (slot / columns | 0) * tile;
        const sample = pixels[name] && atob(pixels[name]);
        for (let y = 0; y < tile; y++) for (let x = 0; x < tile; x++) {
          const sx = Math.max(0,Math.min(size-1,x-gap)), sy = Math.max(0,Math.min(size-1,y-gap));
          const i = ((v+y) * atlasWidth + u+x) * 4, source = (sy*size+sx) * 2;
          if (sample) {
            const color = sample.charCodeAt(source) | sample.charCodeAt(source+1) << 8;
            img.data[i] = (color >> 11) * 255 / 31;
            img.data[i+1] = (color >> 5 & 63) * 255 / 63;
            img.data[i+2] = (color & 31) * 255 / 31;
          } else {
            const grain = ((sx*29+sy*47+sx*sy*7)%33-16)*.61;
            for (let c=0;c<3;c++) img.data[i+c] = surface[name][c]+grain;
          }
          img.data[i+3] = 255;
        }
      }
      ctx.putImageData(img,0,0);
    },atlasWidth,atlasHeight));
    atlas.name = "ashBellSurfaceAtlas";
    atlas.colorSpace = ha;
    atlas.minFilter = YC;
    atlas.generateMipmaps = true;
    return atlas;
  }

  function meshBuilder(material) {
    const batch = new Map();
    const normal = new Y();
    function add(name, tone, geometry, matrix) {
      const uv = geometry.getAttribute("uv"), normals = geometry.getAttribute("normal");
      const slot = tiles.indexOf(name), left = slot%columns*tile, top = (slot/columns|0)*tile;
      const tint = new Float32Array(uv.count*3);
      for (let i=0;i<uv.count;i++) {
        const u=(left+gap+.5+uv.getX(i)*(size-1))/atlasWidth;
        const v=1-(top+gap+.5+(1-uv.getY(i))*(size-1))/atlasHeight;
        uv.setXY(i,u,v);
        normal.fromBufferAttribute(normals,i).transformDirection(matrix);
        const fromTorch = Math.max(0,normal.x);
        const warmth = name==="cast" || name==="belly" ? fromTorch : 0;
        const light = tone*(.57+.25*Math.max(0,normal.z)+.15*Math.max(0,normal.y)+.16*fromTorch);
        tint[i*3]=light*(1+.24*warmth);
        tint[i*3+1]=light*(.965+.071*warmth);
        tint[i*3+2]=light*(.91-.04*warmth);
      }
      geometry.setAttribute("color",new y0(tint,3));
      Yd(batch,material,geometry,matrix);
    }
    function finish(name) {
      const parts = batch.get(material);
      const colors = new Float32Array(parts.reduce((sum,p)=>sum+p.getAttribute("color").array.length,0));
      let cursor=0;
      for (const p of parts) {
        const values = p.getAttribute("color").array;
        colors.set(values,cursor);
        cursor += values.length;
      }
      const geometry = Z(BR(parts));
      geometry.setAttribute("color",new y0(colors,3));
      const object = new pt(geometry,material);
      object.name = name;
      return object;
    }
    const box = (name,tone,w,h,d,x,y,z,ax=0,ay=0,az=0) =>
      add(name,tone,new Ne(w,h,d),E(x,y,z,ax,ay,az));
    const ring = (name,tone,top,base,h,x,y,z,ax=0,az=0,sides=10) =>
      add(name,tone,new Eo(top,base,h,sides),E(x,y,z,ax,0,az));
    function pin(name,tone,a,b,radius,endRadius=radius,facets=7) {
      const from = new Y(...a), to = new Y(...b), length = from.distanceTo(to);
      const axis = to.clone().sub(from).normalize();
      const orient = new Pn().setFromUnitVectors(new Y(0,1,0),axis);
      const matrix = new fe().compose(from.add(to).multiplyScalar(.5),orient,new Y(1,1,1));
      add(name,tone,new Eo(endRadius,radius,length+.004,facets),matrix);
    }
    function plate(name,tone,polygon,depth,front,transform=E(0,0,0)) {
      const shape=new Ku();
      shape.moveTo(...polygon[0]);
      for (const p of polygon.slice(1)) shape.lineTo(...p);
      shape.closePath();
      const g=new hV(shape,{depth:front-depth,bevelEnabled:false});
      const p=g.getAttribute("position"),uv=g.getAttribute("uv");
      const xs=polygon.map(a=>a[0]),ys=polygon.map(a=>a[1]);
      const minX=Math.min(...xs),minY=Math.min(...ys);
      const w=Math.max(...xs)-minX,h=Math.max(...ys)-minY;
      for(let i=0;i<uv.count;i++)uv.setXY(i,(p.getX(i)-minX)/w,(p.getY(i)-minY)/h);
      g.translate(0,0,depth);
      add(name,tone,g,transform);
    }
    function lathe(name,tone,first,second,sides=40,from=0,to=1) {
      const positions=[],uvs=[],normals=[];
      const [r0,startY,v0]=first,[r1,endY,v1]=second;
      const dr=r1-r0,dy=endY-startY,m=Math.hypot(dr,dy);
      function vertex(r,y,v,i) {
        const f=i/sides, a=(from+(to-from)*f)*Math.PI*2;
        const ripple=1+Math.sin(a*7+1.4)*.007+Math.cos(a*11)*.003;
        positions.push(r*Math.sin(a)*ripple,y,r*Math.cos(a)*ripple);
        normals.push(dy*Math.sin(a)/m,-dr/m,dy*Math.cos(a)/m);
        uvs.push(f,v);
      }
      for(let i=0;i<sides;i++){
        vertex(r0,startY,v0,i); vertex(r0,startY,v0,i+1); vertex(r1,endY,v1,i+1);
        vertex(r0,startY,v0,i); vertex(r1,endY,v1,i+1); vertex(r1,endY,v1,i);
      }
      const g=new h0();
      g.setAttribute("position",new y0(new Float32Array(positions),3));
      g.setAttribute("normal",new y0(new Float32Array(normals),3));
      g.setAttribute("uv",new y0(new Float32Array(uvs),2));
      add(name,tone,g,E(0,0,0));
    }
    return {add,finish,box,ring,pin,plate,lathe};
  }

  const xBell = 119.16, zBell = 72.455, pivot = 9.188;
  const bellRotation = -Math.PI/2;

  function foundryBell(scene,material) {
    const m=meshBuilder(material);
    const outer = [
      [1.066,7.756,"inside",.76],[1.124,7.781,"lip",.89],[1.137,7.813,"lip",1.03],
      [1.123,7.849,"cast",1.04],[1.088,7.901,"cast",1.04],[1.062,7.973,"cast",1.04],
      [1.058,8.069,"lip",.99],[1.041,8.098,"cast",1.05],[1.011,8.127,"cast",1.07],
      [.956,8.266,"cast",1.07],[.899,8.412,"cast",1.07],[.844,8.555,"cast",1.07],
      [.788,8.700,"cast",1.07],[.732,8.844,"cast",1.07],[.675,8.989,"cast",1.07],
      [.619,9.133,"cast",1.07],[.546,9.158,"cast",.94],[.361,9.171,"cast",.92],
      [.184,9.174,"iron",.92],[.171,9.228,"ironEdge",.93]
    ];
    // The underside is real hollow geometry with a recessed inner crown.
    const inner = [
      [.211,9.094,"inside",.78],[.43,9.063,"inside",.81],[.61,8.923,"inside",.84],
      [.66,8.745,"inside",.87],[.727,8.562,"inside",.89],[.795,8.384,"inside",.89],
      [.863,8.199,"inside",.89],[.926,8.005,"inside",.91],[.983,7.857,"inside",.93],
      [1.031,7.772,"belly",.68],[1.066,7.756,"inside",.83]
    ];
    function follow(points) {
      for(let i=0;i<points.length-1;i++){
        const a=points[i], b=points[i+1];
        const progress=y=>Math.max(0,Math.min(1,(y-7.75)/1.48));
        m.lathe(a[2],a[3],[a[0],a[1]-pivot,progress(a[1])],
          [b[0],b[1]-pivot,progress(b[1])]);
      }
    }
    follow(outer); follow(inner);
    // Two short rubbed edges catch the warmth already present on the right.
    m.lathe("ash",1.17,[1.143,7.801-pivot,.13],[1.142,7.826-pivot,.35],12,.055,.204);
    m.lathe("ash",.96,[1.065,8.061-pivot,.36],[1.062,8.078-pivot,.47],12,.069,.212);
    m.ring("iron",.85,.066,.059,1.04,0,8.29-pivot,0,0,0,10);
    m.ring("iron",.96,.098,.082,.050,0,7.771-pivot,0,0,0,9);
    m.ring("iron",.92,.096,.122,.174,0,7.651-pivot,0,0,0,8);
    m.ring("ironEdge",.74,.117,.095,.021,0,7.552-pivot,0,0,0,8);
    m.box("belly",.81,.046,.065,.012,.021,7.676-pivot,.113,0,0,-.12);

    // Three narrow casting ribs die out into the dark sand-cast mantle.
    for(const theta of [-.65,.02,.71,2.60,-2.47]) {
      for(const [y,r,y1,r1] of [
        [8.128,1.011,8.412,.901],[8.412,.901,8.700,.791],
        [8.700,.791,8.989,.677],[8.989,.677,9.118,.625]
      ]) {
        m.pin("lip",.62,[Math.sin(theta)*(r+.006),y-pivot,Math.cos(theta)*(r+.006)],
          [Math.sin(theta)*(r1+.004),y1-pivot,Math.cos(theta)*(r1+.004)],.007,.0055,5);
      }
    }
    // The same branch and bell relief turns around the approach plaques.
    function castFace(x,y) {
      const height=pivot+y, index=outer.findIndex(row=>row[1]>height);
      const a=outer[index-1],b=outer[index],t=(height-a[1])/(b[1]-a[1]);
      const radius=a[0]+(b[0]-a[0])*t;
      return Math.sqrt(radius*radius-x*x)+.018;
    }
    ashSprig(m,0,8.408-pivot,castFace,.93);
    const bell=m.finish("ashBellCasting");
    bell.position.set(xBell,pivot,zBell);
    bell.rotation.y=bellRotation;
    scene.add(bell);
    return bell;
  }

  function ashSprig(m,x,y,front,s,matrix=E(0,0,0)) {
    const w=(u,v)=>{
      const px=x+u*s,py=y+v*s;
      return [px,py,typeof front==="function"?front(px,py):front];
    };
    const stem=[[-.007,-.169],[.025,-.077],[.009,.012],[.030,.15]];
    for (let i=1;i<stem.length;i++){
      const a=w(...stem[i-1]),b=w(...stem[i]);
      if(typeof front==="function"){m.pin("ash",.87,a,b,.009*s,.007*s,6);continue;}
      const span=.012*s, silhouette=[[a[0]-span,a[1]],[a[0]+span,a[1]],
        [b[0]+span,b[1]],[b[0]-span,b[1]]];
      m.plate("ash",.93,silhouette,a[2]-.010,a[2]+.005,matrix);
    }
    const leaves = [
      [-.08,-.063,-1], [.094,-.035,1], [-.086,.015,-1], [.089,.058,1],
      [-.041,.098,-1], [.037,.164,1]
    ];
    for (const [u,v,side] of leaves) {
      const [a,b,z]=w(u,v),l=.062*s,h=.029*s;
      const blade=[[a-side*l,b-h*.28],[a-side*l*.73,b+h*.54],
        [a+side*l*.38,b+h],[a+side*l,b+h*.58],
        [a+side*l*.51,b-h*.51],[a-side*l*.14,b-h*.76]];
      m.plate("ash",side<0?.81:1.03,blade,z-.017,z+.008,matrix);
    }
  }

  function beamAndInlay(m) {
    const placement = (x,y,z) => E(x,y,z,0,bellRotation);
    const addBox = (name,tone,w,h,d,u,y,z) =>
      m.add(name,tone,new Ne(w,h,d),placement(xBell-z,y,zBell+u));
    // Heavy oak backed by real ceiling bolts, visible from both hall entrances.
    addBox("oak",.98,3.34,.237,.43,0,9.286,-.038);
    addBox("oakEdge",.91,3.11,.032,.336,.00,9.390,-.06);
    addBox("oak",.87,3.13,.047,.440,-.01,9.171,-.05);
    for(const u of [-1.495,1.48]){
      addBox("iron",.96,.351,.373,.529,u,9.245,-.018);
      addBox("ironEdge",.90,.331,.031,.533,u,9.403,-.024);
      addBox("iron",.93,.242,.395,.342,u,9.301,-.061);
      addBox("ironEdge",.92,.018,.323,.013,u+.154,9.235,.254);
      addBox("ironEdge",.94,.307,.018,.011,u,9.412,.252);
      const world=[xBell-.276,9.240,zBell+u];
      m.ring("ironEdge",.97,.062,.079,.06,...world,0,-Math.PI/2,8);
      m.box("inside",.8,.004,.022,.069,xBell-.309,9.242,zBell+u,0,0,.23);
    }
    addBox("iron",.96,.238,.360,.514,0,9.290,-.017);
    addBox("ironEdge",.92,.164,.057,.372,0,9.160,-.040);
    addBox("ironEdge",.88,.021,.244,.013,-.106,9.270,.251);
    addBox("iron",.94,.182,.126,.394,0,9.161,-.013);
    // A round, shallow bronze inlay around the native seal pickup.
    const loop=64,cx=119.97,cz=72.73,y=6.037;
    function inlaidStrip(tile,tone,from,to,inside,outside,breaks) {
      const positions=[],uv=[],normal=[];
      const node=(radius,i)=>[cx+Math.sin(i/loop*Math.PI*2)*radius,
        y,cz+Math.cos(i/loop*Math.PI*2)*radius];
      for(let i=from;i<to;i++){
        if(breaks.includes(i))continue;
        const a=node(outside,i),b=node(outside,i+1),c=node(inside,i+1),d=node(inside,i);
        const corners=[[a,0,0],[b,1,0],[c,1,1],[a,0,0],[c,1,1],[d,0,1]];
        for(const [p,u,v] of corners){positions.push(...p);uv.push(u,v);normal.push(0,1,0);}
      }
      const g=new h0();
      g.setAttribute("position",new y0(new Float32Array(positions),3));
      g.setAttribute("normal",new y0(new Float32Array(normal),3));
      g.setAttribute("uv",new y0(new Float32Array(uv),2));
      m.add(tile,tone,g,E(0,0,0));
    }
    const chips=[18,19,34,47,48,61];
    inlaidStrip("lip",.97,0,64,.817,.978,chips);
    inlaidStrip("ash",1.34,36,57,.978,1.106,[39,47,48,51]);
  }

  function leverHardware(m,x,z,height) {
    const pivotZ = z+.968;
    const bolt=(x,y) => {
      m.ring("iron",.96,.053,.059,.032,x,y,pivotZ-.117,Math.PI/2,0,8);
      m.box("inside",.9,.056,.012,.004,x,y,pivotZ-.138,0,0,-.32);
    };
    // The native lever at (115,75) retains its interaction and clear floor.
    m.box("oak",.93,.52,.53,.118,x,height+2.377,pivotZ-.067);
    m.box("iron",.94,.395,.405,.122,x,height+2.369,pivotZ-.132);
    m.box("ironEdge",.99,.424,.071,.219,x,height+2.592,pivotZ-.150);
    m.box("iron",.87,.423,.085,.227,x,height+2.161,pivotZ-.147);
    for(const u of [-.155,.155]) for(const v of [2.226,2.524]) bolt(x+u,height+v);
    m.ring("ironEdge",.91,.173,.173,.085,x,height+2.418,pivotZ-.266,Math.PI/2,0,16);
    m.ring("inside",.88,.109,.109,.108,x,height+2.417,pivotZ-.274,Math.PI/2,0,12);
    m.ring("lip",.93,.051,.047,.196,x,height+2.417,pivotZ-.240,Math.PI/2,0,9);
    const rope = [[x-.095,height+2.40,pivotZ-.299],[x-.103,height+2.27,pivotZ-.313],
      [x-.092,height+2.062,pivotZ-.300],[x-.081,height+1.855,pivotZ-.288],
      [x-.071,height+1.60,pivotZ-.292],[x-.079,height+1.345,pivotZ-.279],
      [x-.072,height+1.147,pivotZ-.276]];
    for (let i=1;i<rope.length;i++) {
      m.pin("cord",i%2?.98:.93,rope[i-1],rope[i],.024,.024);
      const a=rope[i-1].map((v,c)=>v+(c===0?.008:c===2?-.015:0));
      const b=rope[i].map((v,c)=>v+(c===0?-.009:c===2?-.012:0));
      m.pin("ash",.79,a,b,.006,.006,5);
    }
    m.ring("ironEdge",.94,.049,.053,.078,x-.073,height+1.176,pivotZ-.276);
    m.ring("oakEdge",.91,.074,.070,.185,x-.073,height+1.067,pivotZ-.278);
    m.ring("iron",.94,.076,.079,.035,x-.073,height+.987,pivotZ-.279);
  }

  function approachPlaque(m,x,worldY,z,scale,second=false) {
    const t=E(x,worldY,z,0,-Math.PI/2,0,scale);
    const p=[[-.346,-.242],[-.257,-.242],[-.257,-.317],[.249,-.317],
      [.249,-.240],[.343,-.240],[.343,.234],[.253,.234],[.253,.317],
      [-.257,.317],[-.257,.241],[-.346,.241]];
    m.plate("iron",.92,p,.005,.041,t);
    m.plate("lip",.83,p.map(([u,v])=>[u*.967,v*.968]),.037,.060,t);
    m.plate("plaque",1.04,p.map(([u,v])=>[u*.927,v*.924]),.055,.078,t);
    function piece(name,tone,g,x,y,z) {
      m.add(name,tone,g,t.clone().multiply(E(x,y,z)));
    }
    for(const u of [-.244,.242]) {
      piece("inside",1.19,new Eo(.046,.053,.018,10).rotateX(Math.PI/2),u,-.003,.093);
      piece("iron",1.02,new Eo(.036,.043,.021,10).rotateX(Math.PI/2),u,-.002,.107);
      piece("inside",.97,new Ne(.035,.010,.006).rotateZ(u<0?.42:-.34),u,-.002,.122);
      piece("ironEdge",.97,new Ne(.023,.010,.005).rotateZ(.56),u-.013,.017,.124);
    }
    ashSprig(m,0,.121,.092,.79,t);
    const bell=[[-.116,-.230],[.112,-.231],[.097,-.200],[.071,-.169],[.063,-.126],
      [.041,-.087],[.003,-.066],[-.034,-.083],[-.054,-.113],[-.068,-.161],[-.101,-.204]];
    m.plate("ash",1.06,bell,.087,.111,t);
    m.plate("lip",.96,bell.map(([u,v])=>[u*.79,-.134+(v+.134)*.83]),.107,.126,t);
    piece("ash",.91,new Eo(.023,.024,.014,8).rotateX(Math.PI/2),0,-.253,.113);

    piece("iron",1.01,new Ne(second?.107:.158,.082,.097),.004,.307,.098);
    piece("inside",1.03,new Ne(second?.068:.112,.053,.014),.004,.305,.151);
    piece("keeper",second?.97:1.34,new Ne(second?.037:.071,.034,.017),.004,.305,.163);
    piece("ash",1.69,new Ne(second?.010:.021,.016,.013),-.005,.309,.176);
    piece("ironEdge",1.00,new Ne(second?.124:.179,.024,.123).rotateX(-.12),.004,.352,.119);
  }

  function buildChamber(scene, map) {
    const atlas=surfaceAtlas();
    const material=Z(new $e({map:atlas,vertexColors:true,toneMapped:false,side:hi}));
    const still = meshBuilder(material);
    beamAndInlay(still);
    const [leverX,leverZ] = map.script.lever.map(n=>(n+.5)*P);
    leverHardware(still,leverX,leverZ,ie(leverX,leverZ));
    approachPlaque(still,115.993,6.54,66.94,1.0);
    approachPlaque(still,115.993,6.88,69.12,.91,true);
    scene.add(still.finish("ashBellChamberFittings"));
    const bell=foundryBell(scene,material);
    activeBells.set(scene,{bell,t:-1});
  }

  const decorate=FJ;
  FJ=function(scene,map) {
    decorate.apply(this,arguments);
    if(T.level!==level || map.script?.lever?.[0]!==57 || map.script.lever[1]!==37) return;
    if(map.script?.lift?.cells?.[0]?.[1]!==38 || v.grid[36]?.[60]==="#") return;
    buildChamber(scene,map);
  };

  const ringNativeBell = PH;
  PH = function() {
    const previous=de.bell;
    const result=ringNativeBell.apply(this,arguments);
    const hanging = activeBells.get(J.scene);
    if(hanging && !previous && de.bell)hanging.t=0;
    return result;
  };

  const stepLift = HH;
  HH = function(dt) {
    const result=stepLift.apply(this,arguments);
    if(T.level!==level) return result;
    const hanging=activeBells.get(J.scene);
    if(!hanging || hanging.t<0)return result;
    hanging.t+=dt;
    if(hanging.t>=5.7){
      hanging.bell.rotation.x=0;
      hanging.t=-1;
    } else {
      hanging.bell.rotation.x=.094*Math.exp(-.64*hanging.t)*Math.sin(hanging.t*7.1);
    }
    return result;
  };
})();
/* ASH_BELL_CHAMBER_END */
